toolArgs.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@inject sv_1ba2ce6c31a74afe9f674686533edcf7.Services.InventoryAlertService AlertService
@inject sv_1ba2ce6c31a74afe9f674686533edcf7.Services.WarehouseState WarehouseState
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title text-danger">Low Stock Alerts</h5>
                <p class="display-4 fw-bold text-danger">@AlertService.LowStockCount</p>
                <p class="text-muted">Items below minimum level</p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertDataChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();
        AlertService.OnAlertDataChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

